package com.masona.pocketledger;
import android.app.job.*;import android.content.*;import org.json.*;import javax.net.ssl.HttpsURLConnection;import java.net.URL;import java.io.*;import java.util.concurrent.*;
public class SyncJob extends JobService {
 static final String ORIGIN="https://95.217.214.201:8446";private static final ExecutorService WORK=Executors.newSingleThreadExecutor();
 static void schedule(Context c){JobScheduler s=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);s.schedule(new JobInfo.Builder(4101,new ComponentName(c,SyncJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setPeriodic(15*60*1000L).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());}
 static void kick(Context c){Context app=c.getApplicationContext();WORK.execute(()->sync(app));}
 static JSONObject request(String path,JSONObject body,String token)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(ORIGIN+path).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);byte[] bytes=body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream o=c.getOutputStream()){o.write(bytes);}int code=c.getResponseCode();if(code!=200){c.disconnect();throw new IOException(code==401?"Phone access expired. Pair again.":"Sync unavailable ("+code+"). Saved messages will retry.");}try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>1024*1024)throw new IOException("Unexpected response size.");}return new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}}
 static boolean sync(Context context){try(Vault vault=new Vault(context)){String t=vault.token();if(t==null)return true;for(int batch=0;batch<10;batch++){JSONArray events=vault.pending();if(events.length()==0)break;JSONObject response=request("/device/sync",new JSONObject().put("events",events),t);JSONArray ack=response.getJSONArray("acknowledged"),rejected=response.getJSONArray("rejected");for(int i=0;i<ack.length();i++)vault.acknowledge(ack.getJSONObject(i).getString("eventId"));for(int i=0;i<rejected.length();i++)vault.rejected(rejected.getJSONObject(i).getString("eventId"));if(ack.length()+rejected.length()==0)throw new IOException("Server did not confirm messages.");}context.getSharedPreferences("ledger",0).edit().putString("sync_status","Last sync: "+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date())).apply();return true;}catch(Exception e){context.getSharedPreferences("ledger",0).edit().putString("sync_status",e.getMessage()==null?"Offline — messages saved for later":e.getMessage()).apply();return false;}}
 public boolean onStartJob(JobParameters params){WORK.execute(()->jobFinished(params,!sync(this)));return true;}
 public boolean onStopJob(JobParameters params){return true;}
}
